config.expr:
let day = (today ?? "") != "" ? today : clock[:10];
let open = filter(mine ?? [], (#.state ?? "active") == "active" && (#.completedAt ?? "") == "");
let row = map(open, ({id: #._id, title: #.title, project: #.project, status: #.status ?? "", due: #.due ?? "", priority: #.priority ?? "none", version: #._seq}));
{today: day,
 due: filter(row, #.due != "" && #.due <= day),
 later: filter(row, #.due == "" || #.due > day),
 proposals: map(filter(mine ?? [], #.state == "proposed"), ({id: #._id, title: #.title, project: #.project, proposedBy: #.proposedBy ?? "", source: #.source}))}
